const leads = $input.all();

const totalLeads = leads.length;

let hotLeads = 0;
let warmLeads = 0;
let coldLeads = 0;

let contacted = 0;
let followUpSent = 0;
let needsAttention = 0;
let salesNotified = 0;

let totalScore = 0;
let scoreCount = 0;

let totalBudget = 0;

for (const item of leads) {
  const lead = item.json;

  const category = String(lead["Lead Category"] || "").trim();
  const status = String(lead["Status"] || "").trim();

  const score = Number(lead["AI Score"]);
  const budget = Number(
    String(lead["Estimated Budget"] || "")
      .replace(/[^0-9.-]/g, "")
  );

  if (category === "Hot") hotLeads++;
  if (category === "Warm") warmLeads++;
  if (category === "Cold") coldLeads++;

  if (status === "Contacted") contacted++;
  if (status === "Follow-up Sent") followUpSent++;
  if (status === "Needs Attention") needsAttention++;
  if (status === "Sales Notified") salesNotified++;

  if (!isNaN(score) && score > 0) {
    totalScore += score;
    scoreCount++;
  }

  if (!isNaN(budget)) {
    totalBudget += budget;
  }
}

const averageScore = scoreCount
  ? Math.round(totalScore / scoreCount)
  : 0;

return [
  {
    json: {
      totalLeads,
      hotLeads,
      warmLeads,
      coldLeads,
      contacted,
      followUpSent,
      needsAttention,
      salesNotified,
      averageScore,
      totalBudget
    }
  }
];
